if($page==='ai-regenerate'&&is_post()){require_login();verify_csrf();$id=(int)($_POST['assessment_id']??0);$s=db()->prepare('SELECT ai_generated_at FROM assessments WHERE id=? AND user_id=?');$s->execute([$id,user()['id']]);$genAt=$s->fetchColumn();if($genAt){$diff=time()-strtotime((string)$genAt);if($diff<180){$wait=180-$diff;flash('warning',"Vui lòng đợi thêm {$wait} giây trước khi yêu cầu AI phân tích lại (thời gian chờ tối thiểu 3 phút).");redirect('index.php?page=result&id='.$id);}}generate_assessment_ai($id,(int)user()['id']);flash('success','AI đã phân tích lại hồ sơ hướng nghiệp của bạn.');redirect('index.php?page=result&id='.$id);}
if($page==='simulation-complete'&&is_post()){require_login();verify_csrf();$careerId=(int)($_POST['career_id']??0);$s=db()->prepare("SELECT * FROM careers WHERE id=? AND status='published'");$s->execute([$careerId]);$career=$s->fetch();$game=$career?simulation_for_career($career):null;if(!$career||!$game){http_response_code(404);exit('Mô phỏng không tồn tại hoặc đang tạm đóng.');}$decisions=json_decode((string)($_POST['decisions']??'[]'),true);$missionKeys=json_decode((string)($_POST['mission_keys']??'[]'),true);if(!is_array($decisions)){http_response_code(422);exit('Dữ liệu lựa chọn không hợp lệ.');}try{$result=calculate_simulation_result($game,$decisions,is_array($missionKeys)?$missionKeys:[]);$duration=max(1,min(7200,(int)($_POST['duration']??0)));$feeling=in_array($_POST['reflection_feeling']??'',['excited','challenged','unsuited'],true)?$_POST['reflection_feeling']:'excited';$note=mb_substr(trim((string)($_POST['reflection_note']??'')),0,300);$s=db()->prepare('INSERT INTO simulation_attempts(user_id,career_id,score,decisions,skill_scores,duration_seconds,reflection_feeling,reflection_note) VALUES(?,?,?,?,?,?,?,?)');$s->execute([user()['id'],$careerId,$result['score'],json_encode($result['decisions']),json_encode($result['skills']),$duration,$feeling,$note]);$attemptId=(int)db()->lastInsertId();audit('Hoàn thành mô phỏng nghề','simulation_attempt',$attemptId);redirect('index.php?page=simulation-result&id='.$attemptId);}catch(InvalidArgumentException $e){http_response_code(422);exit(e($e->getMessage()));}}
if($page==='assessment'&&is_post()){require_login();verify_csrf();$questions=db()->query("SELECT * FROM questions WHERE status='active' ORDER BY sort_order,id")->fetchAll();$answers=is_array($_POST['answers']??null)?$_POST['answers']:[];$valid=count($questions)>=6;foreach($questions as $q){$value=(int)($answers[$q['id']]??0);if($value<1||$value>5){$valid=false;break;}}if(!$valid){flash('error','Vui lòng trả lời đầy đủ các câu hỏi.');}else{$durationSec=max(0,min(7200,(int)($_POST['duration_seconds']??0)));$scientific=score_assessment_scientific($answers,$questions,[],$durationSec);$scores=$scientific['raw_scores'];$code=$scientific['result_code'];db()->beginTransaction();try{recommendations_lock_user((int)user()['id']);$s=db()->prepare('INSERT INTO assessments(user_id,answers,scores,ipsative_z_scores,validity_metrics,result_code,ai_status) VALUES(?,?,?,?,?,?,\'pending\')');$s->execute([user()['id'],json_encode($answers),json_encode($scores),json_encode($scientific['ipsative_z_scores']),json_encode($scientific['validity_metrics'],JSON_UNESCAPED_UNICODE),$code]);$assessmentId=(int)db()->lastInsertId();db()->commit();audit('Hoàn thành trắc nghiệm Holland','assessment',$assessmentId);unset($_SESSION['assessment_draft']);redirect('index.php?page=constraints&id='.$assessmentId);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}}

if(in_array($page,['login','register'],true)){$pageTitle=$page==='login'?'Đăng nhập':'Đăng ký';require __DIR__.'/app/header.php';?><div class="auth-wrap"><div class="auth-card"><span class="eyebrow"><?=$page==='login'?'Chào mừng trở lại':'Bắt đầu hành trình'?></span><h1><?=$page==='login'?'Đăng nhập':'Tạo tài khoản'?></h1><p class="muted"><?=$page==='login'?'Tiếp tục khám phá tương lai của bạn.':'Lưu kết quả và theo dõi hành trình nghề nghiệp.'?></p><form method="post"><?=csrf_field()?><?php if($page==='register'):?><div class="form-group"><label for="auth-name">Họ và tên</label><input id="auth-name" class="input" name="name" value="<?=e($_POST['name']??'')?>" autocomplete="name" required></div><div class="form-row"><div class="form-group"><label for="auth-grade">Lớp</label><select id="auth-grade" name="grade"><option value="">Chọn lớp</option><?php for($i=6;$i<=12;$i++):?><option>Lớp <?=$i?></option><?php endfor;?></select></div><div class="form-group"><label for="auth-school">Trường học</label><input id="auth-school" class="input" name="school" autocomplete="organization"></div></div><?php endif;?><div class="form-group"><label for="auth-email">Email</label><input id="auth-email" class="input" type="email" name="email" autocomplete="email" required></div><div class="form-group"><label for="auth-password">Mật khẩu</label><input id="auth-password" class="input" type="password" name="password" autocomplete="<?=$page==='login'?'current-password':'new-password'?>" minlength="8" required></div><?php if($page==='register'):?><label class="flex items-start gap-2 text-sm text-slate-600"><input class="mt-1" type="checkbox" name="agree" value="1" required> Tôi đồng ý sử dụng kết quả với mục đích tham khảo hướng nghiệp.</label><?php endif;?><button class="btn btn-primary btn-lg mt-5 w-full"><?=$page==='login'?'Đăng nhập':'Đăng ký miễn phí'?></button></form><p class="mt-6 text-center"><?=$page==='login'?'Chưa có tài khoản? <a class="font-bold text-brand-600" href="'.url('index.php?page=register').'">Đăng ký</a>':'Đã có tài khoản? <a class="font-bold text-brand-600" href="'.url('index.php?page=login').'">Đăng nhập</a>'?></p></div></div><?php require __DIR__.'/app/footer.php';exit;}

if($page==='assessment'){require_login();if(setting('assessment_enabled','1')!=='1')exit('Bài trắc nghiệm đang tạm đóng.');$questions=db()->query("SELECT * FROM questions WHERE status='active' ORDER BY sort_order,id")->fetchAll();if(!$questions)exit('Ngân hàng câu hỏi chưa sẵn sàng.');$pageTitle='Khám phá sở thích & thế mạnh';require __DIR__.'/app/header.php';?><div class="assessment-wrap"><div class="mb-4 flex items-center justify-between gap-4"><div><span class="badge badge-purple">✦ Khảo sát sở thích Holland (RIASEC)</span><h1 class="mt-2 text-2xl font-black">Khám phá bản thân</h1></div><div class="text-right"><b id="progressText">Câu 1 / <?=count($questions)?></b><small id="saveStatus" class="block text-slate-400">Tiến độ được lưu trên thiết bị</small></div></div><div class="progress-track"><div id="progressBar" class="progress-bar" style="width:<?=100/count($questions)?>%"></div></div><div class="my-4 flex flex-wrap justify-between gap-2 text-xs font-semibold text-slate-400"><span>Hãy chọn mức độ phản ánh đúng nhất với bạn trong thời gian gần đây</span><button id="resetDraft" type="button" class="text-brand-600 hover:underline">Làm lại từ đầu</button></div><form method="post" id="assessmentForm" data-submit-loading><?=csrf_field()?><input type="hidden" name="duration_seconds" id="riasecDurationSeconds" value="0"><?php foreach($questions as $i=>$q):$qMeta=riasec_question_meta($q['riasec_type'],(int)$q['sort_order']);?><section class="card question <?=$i===0?'active':''?>" data-index="<?=$i?>"><div class="flex items-center justify-between mb-2"><span class="badge badge-subtle"><?=e($qMeta['icon'].' '.$qMeta['label'])?></span><span class="text-sm font-bold text-slate-400"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span></div><h2 class="text-lg font-bold text-slate-900 mb-1"><?=e($q['content'])?></h2><p class="text-xs text-slate-500 mb-4"><?=e($qMeta['context'])?></p><div class="scale"><?php foreach([1=>'Hoàn toàn không',2=>'Ít đúng',3=>'Phân vân',4=>'Khá đúng',5=>'Rất đúng'] as $v=>$label):?><input type="radio" id="q<?=$q['id']?>-<?=$v?>" name="answers[<?=$q['id']?>]" value="<?=$v?>" data-question="<?=$q['id']?>"><label for="q<?=$q['id']?>-<?=$v?>"><b><?=$v?></b><span><?=$label?></span></label><?php endforeach;?></div><div class="question-actions mt-6 flex items-center justify-between"><button type="button" class="btn btn-outline prev" <?=$i===0?'disabled':''?>>← Câu trước</button><?php if($i<count($questions)-1):?><button type="button" class="btn btn-primary next">Câu tiếp theo →</button><?php else:?><button class="btn btn-primary btn-lg" type="submit">Hoàn thành & Xem kết quả →</button><?php endif;?></div></section><?php endforeach;?></form></div><div id="loadingOverlay" class="loading-overlay"><div class="loading-panel"><div class="spinner"></div><span class="badge badge-purple">✦ Đang phân tích</span><h2 class="my-4 text-2xl font-black">Đang tổng hợp hồ sơ của bạn</h2><p class="text-slate-500">Hệ thống đang đối chiếu 6 nhóm sở thích và chuẩn bị gợi ý nghề nghiệp phù hợp.</p></div></div><script>const startedAt=Date.now(),qs=[...document.querySelectorAll('.question')],bar=document.getElementById('progressBar'),txt=document.getElementById('progressText'),save=document.getElementById('saveStatus'),durInput=document.getElementById('riasecDurationSeconds'),draftKey='jobsimu_riasec_<?=user()['id']?>';let current=0;function show(n){qs[current].classList.remove('active');current=Math.max(0,Math.min(n,qs.length-1));qs[current].classList.add('active');bar.style.width=((current+1)/qs.length*100)+'%';txt.textContent=`Câu ${current+1} / ${qs.length}`;localStorage.setItem(draftKey+'_current',current);scrollTo({top:70,behavior:'smooth'})}function saveDraft(){const data={};document.querySelectorAll('input[type=radio]:checked').forEach(i=>data[i.dataset.question]=i.value);localStorage.setItem(draftKey,JSON.stringify(data));save.textContent='✓ Đã tự động lưu';setTimeout(()=>save.textContent='Tiến độ được lưu trên thiết bị',1600)}try{const data=JSON.parse(localStorage.getItem(draftKey)||'{}');Object.entries(data).forEach(([q,v])=>document.querySelector(`[data-question="${q}"][value="${v}"]`)?.click());const saved=Number(localStorage.getItem(draftKey+'_current')||0);if(saved>0&&saved<qs.length)show(saved)}catch(e){}document.querySelectorAll('input[type=radio]').forEach(i=>i.addEventListener('change',saveDraft));document.querySelectorAll('.next').forEach(b=>b.onclick=()=>{if(!qs[current].querySelector('input:checked')){showToast('Hãy chọn một mức độ phù hợp với bạn.');return}show(current+1)});document.querySelectorAll('.prev').forEach(b=>b.onclick=()=>show(current-1));document.getElementById('assessmentForm').addEventListener('submit',()=>{if(durInput)durInput.value=String(Math.max(1,Math.round((Date.now()-startedAt)/1000)));});document.getElementById('resetDraft').onclick=()=>{if(confirm('Xóa toàn bộ câu trả lời đã lưu và làm lại?')){localStorage.removeItem(draftKey);localStorage.removeItem(draftKey+'_current');document.querySelectorAll('input[type=radio]').forEach(i=>i.checked=false);show(0)}};</script><?php require __DIR__.'/app/footer.php';exit;}

if($page==='result'){require_login();recommendations_refresh_current((int)user()['id']);$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM assessments WHERE id=? AND user_id=?');$s->execute([$id,user()['id']]);$r=$s->fetch();if(!$r)exit('Không tìm thấy kết quả.');$scores=json_decode($r['scores'],true);$efficacyScores=json_decode($r['efficacy_scores']??'{}',true)?:[];$zScores=json_decode($r['ipsative_z_scores']??'{}',true)?:[];$validityMetrics=json_decode($r['validity_metrics']??'{}',true)?:[];$advice=json_decode($r['ai_advice']?:'{}',true);$s=db()->prepare('SELECT c.*,m.match_percent,m.rank_order FROM assessment_matches m JOIN careers c ON c.id=m.career_id WHERE m.assessment_id=? ORDER BY m.rank_order');$s->execute([$id]);$matches=$s->fetchAll();$userSims=[];$simS=db()->prepare('SELECT career_id,score,reflection_feeling,reflection_note,completed_at FROM simulation_attempts WHERE user_id=? ORDER BY completed_at DESC');$simS->execute([user()['id']]);foreach($simS->fetchAll() as $srow){if(!isset($userSims[$srow['career_id']]))$userSims[$srow['career_id']]=$srow;}$pageTitle='Hồ sơ sở thích Holland '.$r['result_code'];require __DIR__.'/app/header.php';?><section class="page-head"><div class="container"><nav class="breadcrumb mb-3" aria-label="Đường dẫn trang"><a href="<?=url('index.php?page=home')?>">Trang chủ</a><span class="breadcrumb-sep">/</span><a href="<?=url('index.php?page=assessment-hub')?>">Hiểu bản thân</a><span class="breadcrumb-sep">/</span><span aria-current="page">Kết quả Holland</span></nav><div class="flex flex-wrap items-center justify-between gap-4"><div><span class="badge badge-purple mb-2">Hồ sơ sở thích nghề nghiệp</span><h1 class="page-title mb-1">Mã Holland của bạn: <span class="text-brand-600"><?=e($r['result_code'])?></span></h1><p class="page-subtitle">Ngày hoàn thành: <?=date('d/m/Y',strtotime($r['completed_at']))?> · Khảo sát 30 câu hỏi theo chuẩn O*NET</p></div><div class="flex flex-wrap gap-2"><a class="btn btn-outline btn-sm" href="<?=url('index.php?page=assessment')?>">↻ Làm lại trắc nghiệm</a><a class="btn btn-primary btn-sm" href="<?=url('index.php?page=assessment-report')?>">Mở báo cáo tổng hợp →</a></div></div></div></section><div class="container py-8 space-y-8"><!-- 1. ĐIỀU ĐÁNG CHÚ Ý --><section class="card p-6" aria-labelledby="sec-highlights"><h2 id="sec-highlights" class="text-lg font-bold text-slate-900 mb-3 flex items-center gap-2"><span>✨</span> 1. Điều đáng chú ý từ kết quả của bạn</h2><div class="p-4 bg-purple-50/60 rounded-xl border border-purple-100 text-slate-800 text-base leading-relaxed mb-4"><?=e($advice['summary']??'Hồ sơ của bạn cho thấy sự nổi bật ở các nhóm sở thích chính. Hãy đối chiếu các gợi ý dưới đây với đam mê thực tế của bạn.')?></div><?php if(!empty($advice['strengths'])):?><div class="mb-4"><h3 class="text-sm font-bold text-slate-800 mb-2">Điểm mạnh tiềm năng nổi bật:</h3><ul class="list-disc pl-5 text-sm text-slate-700 space-y-1"><?php foreach($advice['strengths'] as $st):?><li><?=e($st)?></li><?php endforeach;?></ul></div><?php endif;?><?php if(!empty($advice['reality_check'])):?><div class="p-4 bg-blue-50/70 border border-blue-100 rounded-xl text-xs text-blue-900 leading-relaxed"><strong>🔍 Điểm cần lưu ý & Đối chiếu thực tế:</strong> <?=e($advice['reality_check'])?></div><?php endif;?></section><!-- 2. GIỚI HẠN DIỄN GIẢI --><section class="notice-box" aria-labelledby="sec-limits"><h2 id="sec-limits" class="text-sm font-bold text-slate-900 mb-2 flex items-center gap-2"><span>ℹ️</span> 2. Giới hạn diễn giải & Lưu ý phương pháp</h2><p class="text-xs text-slate-600 leading-relaxed mb-2">Kết quả này được tổng hợp dựa trên câu trả lời tự khai của bạn tại thời điểm khảo sát. Sở thích và sự tự tin của bạn sẽ tiếp tục phát triển theo trải nghiệm học tập và đời sống. Đây là công cụ gợi ý hướng tìm hiểu, không phải kết luận năng lực tuyệt đối hay phán quyết cố định về sự phù hợp nghề.</p><?php if(!empty($validityMetrics['warning_message'])):?><p class="text-xs font-s