ol class="list-decimal pl-5 text-xs text-slate-700 space-y-1.5"><?php foreach($advice['next_steps'] as $ns):?><li><?=e($ns)?></li><?php endforeach;?></ol></div><?php endif;?></section><!-- 4. BIỂU ĐỒ CHI TIẾT 6 NHÓM SỞ THÍCH --><section class="card p-6" aria-labelledby="sec-scores"><div class="flex items-center justify-between mb-4"><div><h2 id="sec-scores" class="text-lg font-bold text-slate-900">4. Chi tiết điểm số 6 nhóm RIASEC</h2><p class="text-xs text-slate-500">Đối chiếu mức độ hứng thú tự khai và mức độ tự tin thực hiện công việc.</p></div></div><div class="score-grid"><?php foreach($scores as $type=>$score):$zVal=isset($zScores[$type])?(float)$zScores[$type]:null;$effVal=isset($efficacyScores[$type])?(int)$efficacyScores[$type]:null;?><div class="score-item"><div class="score-ring" style="--v:<?=$score?>;--c:<?=riasec_colors()[$type]?>"><span><?=$score?>%</span></div><b class="text-sm"><?=e(riasec_labels()[$type])?> (<?=$type?>)</b><small class="muted"><?php if($effVal!==null):?>Tự tin: <?=$effVal?>%<?php else:?>Sở thích: <?=$score?>%<?php endif;?></small></div><?php endforeach;?></div><div class="mt-6 pt-4 border-t border-slate-100 flex flex-wrap items-center justify-between gap-3 text-xs"><form method="post" action="<?=url('index.php?page=ai-regenerate')?>" data-submit-loading><?=csrf_field()?><input type="hidden" name="assessment_id" value="<?=$id?>"><button class="btn btn-outline btn-sm">↻ Cập nhật phân tích định hướng</button></form><a class="btn btn-outline btn-sm" href="<?=url('index.php?page=assessment-hub')?>">Làm thêm bài đánh giá Big Five & CAAS →</a></div></section></div><div id="loadingOverlay" class="loading-overlay"><div class="loading-panel"><div class="spinner"></div><h2 class="text-2xl font-black">AI đang cập nhật phân tích</h2><p class="mt-2 text-slate-500">Vui lòng chờ trong giây lát.</p></div></div><?php require __DIR__.'/app/footer.php';exit;}

